    /// <summary>
    /// Returns a readable path for the named fixture. Prefers the on-disk
    /// TestData file when present; otherwise writes the embedded bytes to a
    /// temp file and returns that path.
    /// </summary>
    public static string EnsureTestData(string fileName)
    {
        var dir = AppContext.BaseDirectory;
        var onDisk = Path.Combine(dir, "TestData", fileName);
        if (File.Exists(onDisk)) return onDisk;
        var repoRelative = Path.Combine(Directory.GetCurrentDirectory(), "TestData", fileName);
        if (File.Exists(repoRelative)) return repoRelative;

        var bytes = Convert.FromBase64String(PngBase64);
        var tempDir = Path.Combine(Path.GetTempPath(), "DocuArchiveTestData");
        Directory.CreateDirectory(tempDir);
        var tempPath = Path.Combine(tempDir, fileName);
        File.WriteAllBytes(tempPath, bytes);
        return tempPath;
    }
}
